/**
 * Todoist API client wrapper
 * 
 * Usage:
 * const client = new TodoistClient('YOUR_API_TOKEN');
 * const tasks = await client.getTasks();
 * await client.createTask({ content: 'Buy milk', due_string: 'tomorrow' });
 * await client.completeTask('2995104339');
 */

interface Task {
  id: string;
  content: string;
  project_id?: string;
  due?: { date?: string; string?: string; datetime?: string };
}

interface CreateTaskParams {
  content: string;
  project_id?: string;
  due_string?: string;
  due_date?: string;
  due_datetime?: string;
  priority?: number;
}

class TodoistClient {
  private apiBase = 'https://api.todoist.com/rest/v2';
  private headers: Record<string, string>;

  constructor(private token: string) {
    this.headers = {
      'Authorization': `Bearer ${this.token}`,
      'Content-Type': 'application/json',
    };
  }

  async getTasks(projectId?: string): Promise<Task[]> {
    const url = new URL(`${this.apiBase}/tasks`);
    if (projectId) url.searchParams.append('project_id', projectId);
    const res = await fetch(url.toString(), { headers: this.headers });
    if (!res.ok) throw new Error(`GET /tasks failed: ${res.status} ${res.statusText}`);
    return res.json() as Promise<Task[]>;
  }

  async createTask(params: CreateTaskParams): Promise<Task> {
    const res = await fetch(`${this.apiBase}/tasks`, {
      method: 'POST',
      headers: this.headers,
      body: JSON.stringify(params),
    });
    if (!res.ok) throw new Error(`POST /tasks failed: ${res.status} ${res.statusText}`);
    return res.json() as Promise<Task>;
  }

  async completeTask(taskId: string): Promise<void> {
    const res = await fetch(`${this.apiBase}/tasks/${taskId}/close`, {
      method: 'POST',
      headers: this.headers,
    });
    if (!res.ok) throw new Error(`POST /tasks/${taskId}/close failed: ${res.status} ${res.statusText}`);
  }
}

export { TodoistClient, Task, CreateTaskParams };
