import sqlite3
from collections import deque

class TaskQueue(ABC):
    @abstractmethod
    def enqueue(self, task):
        pass

    @abstractmethod
    def dequeue(self):
        pass

class InMemoryTaskQueue(TaskQueue):
    def __init__(self):
        self._queue = deque()

    def enqueue(self, task):
        self._queue.append(task)

    def dequeue(self):
        return self._queue.popleft() if self._queue else None

class SQLiteTaskQueue(TaskQueue):
    def __init__(self, db_path=':memory:'):
        self.conn = sqlite3.connect(db_path)
        self.conn.execute('CREATE TABLE IF NOT EXISTS tasks (id INTEGER PRIMARY KEY, task TEXT)')

    def enqueue(self, task):
        self.conn.execute('INSERT INTO tasks (task) VALUES (?)', (task,))
        self.conn.commit()

    def dequeue(self):
        cursor = self.conn.execute('SELECT id, task FROM tasks ORDER BY id LIMIT 1')
        row = cursor.fetchone()
        if row:
            self.conn.execute('DELETE FROM tasks WHERE id = ?', (row[0],))
            self.conn.commit()
            return row[1]
        return None"}

