pub struct Fahrenheit(pub f64);
impl Fahrenheit {
    pub fn new(value: f64) -> Self { Fahrenheit(value) }
}
impl TemperatureScale for Fahrenheit {
    fn to_celsius(&self) -> f64 { (self.0 - 32.0) * 5.0 / 9.0 }
    fn from_celsius(celsius: f64) -> Self { Fahrenheit(celsius * 9.0 / 5.0 + 32.0) }
}

pub struct Kelvin(pub f64);
impl Kelvin {
    pub fn new(value: f64) -> Self { Kelvin(value) }
}
impl TemperatureScale for Kelvin {
    fn to_celsius(&self) -> f64 { self.0 - 273.15 }
