import fetch from 'node-fetch';

export class ApiError extends Error {
  constructor(public status: number, message: string, public body: any) {
    super(message);
    this.name = 'ApiError';
  }
}

interface RequestOptions {
  method?: 'GET' | 'POST' | 'DELETE';
  query?: Record<string, string | number | boolean>;
  body?: Record<string, any>;
}

interface ApiResponse<T> {
  data: T;
  status: number;
}

class StripeClient {
  private apiKey: string;
  private baseUrl = 'https://api.stripe.com/v1';

  constructor(apiKey: string) {
    this.apiKey = apiKey;
  }

  private async request<T>(path: string, options: RequestOptions = {}): Promise<ApiResponse<T>> {
    const { method = 'GET', query, body } = options;
    const url = new URL(this.baseUrl + path);
    if (query) {
      Object.entries(query).forEach(([key, value]) => url.searchParams.append(key, String(value)));
    }
    const headers: Record<string, string> = {
      'Authorization': `Bearer ${this.apiKey}`,
      'Content-Type': 'application/x-www-form-urlencoded'
    };
    let init: RequestInit = { method, headers };
    if (body && method !== 'GET') {
      const params = new URLSearchParams();
      Object.entries(body).forEach(([key, value]) => params.append(key, String(value)));
      init.body = params.toString();
    }
    const response = await fetch(url.toString(), init);
    const data = await response.json().catch(() => ({}));
    if (!response.ok) {
      throw new ApiError(response.status, `Stripe API error: ${data.error?.message || 'Unknown'}`, data);
    }
    return { data: data as T, status: response.status };
  }

  // Customers
  listCustomers(params?: { limit?: number }) {
    return this.request<{ data: Customer[] }>('/customers', { query: params });
  }

  getCustomer(id: string) {
    return this.request<Customer>(`/customers/${id}`);
  }

  createCustomer(data: { email?: string; name?: string }) {
    return this.request<Customer>('/customers', { method: 'POST', body: data });
  }

  deleteCustomer(id: string) {
    return this.request<{ deleted: boolean }>(`/customers/${id}`, { method: 'DELETE' });
  }

  // Charges
  createCharge(data: { amount: number; currency: string; customer?: string; source?: string }) {
    return this.request<Charge>('/charges', { method: 'POST', body: data });
  }

  listCharges(params?: { customer?: string; limit?: number }) {
    return this.request<{ data: Charge[] }>('/charges', { query: params });
  }
}

// Example interfaces (simplified)
export interface Customer {
  id: string;
  email?: string;
  name?: string;
}

export interface Charge {
  id: string;
  amount: number;
  currency: string;
  customer?: string;
}

export default StripeClient;
EOF"}

