required_cols = ['date', 'station_id', 'temp_c', 'humidity', 'wind_kph']

# Check file exists and non-empty
if not file_path.exists():
    print(f'ERROR: {file_path} does not exist')
    sys.exit(1)
if file_path.stat().st_size == 0:
    print('ERROR: file is empty')
    sys.exit(1)

failed = []
total = 0
with open(file_path, 'r') as f:
    reader = csv.DictReader(f)
    # Check columns
    missing = [c for c in required_cols if c not in reader.fieldnames]
    if missing:
        print(f'ERROR: missing columns: {missing}')
        sys.exit(1)
    for row in reader:
        total += 1
        row_errors = []
        # Check nulls
        for col in required_cols:
            if not row.get(col):
                row_errors.append(f'null {col}')
        # Range checks
        try:
            temp = float(row['temp_c'])
            if temp < -50 or temp > 50:
                row_errors.append(f'temp_c {temp} out of range')
        except ValueError:
            row_errors.append('temp_c invalid number')
        try:
            hum = float(row['humidity'])
            if hum < 0 or hum > 100:
                row_errors.append(f'humidity {hum} out of range')
        except ValueError:
            row_errors.append('humidity invalid number')
        try:
            wind = float(row['wind_kph'])
            if wind < 0 or wind > 200:
                row_errors.append(f'wind_kph {wind} out of range')
        except ValueError:
            row_errors.append('wind_kph invalid number')
        if row_errors:
            failed.append((row.get('date', '?'), row_errors))

passed = total - len(failed)
print(f'Total rows: {total}')
print(f'Rows passed: {passed}')
print(f'Rows failed: {len(failed)}')
if failed:
    for date, errs in failed[:5]:
        print(f'Row {date}: {errs}')
    sys.exit(1)
else:
    print('ALL CHECKS PASSED')
    sys.exit(0)
"}

